/*
 * A006697  Number of subwords of length n in infinite word generated by a ->
 *          aab, b -> b.
 * https://oeis.org/A006697
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy, nice
 * Formula:   a(n) = Sum_{k=0..n} min(2^k, n-k+1)
 * Range:     u8 n <= 24, u16 n <= 368, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n) {
    seq_t result = 0;
    idx_t k;
    for (k = 0; k <= n; k++) {
        idx_t r = n - k + 1;
        if (k >= 63 || ((uint64_t)1 << k) >= r) {
            /* remaining terms are r, r-1, ..., 1 */
            seq_t rs = (seq_t)r;
            if (r % 2 == 0)
                result += (rs / 2) * (rs + 1);
            else
                result += rs * ((rs + 1) / 2);
            break;
        }
        result += (seq_t)((uint64_t)1 << k);
    }
    return result;
}
